-- Control: todas las metas fuente deben existir antes de insertar.
DO $$
DECLARE
    faltantes integer;
BEGIN
    SELECT COUNT(*)
    INTO faltantes
    FROM stg_propuesta_ciudadana s
    LEFT JOIN meta_proyecto m
      ON m.codigo_meta_extendida = s.codigo_meta_extendida
    WHERE m.id_meta IS NULL;

    IF faltantes > 0 THEN
        RAISE EXCEPTION 'Existen % propuestas con una meta no encontrada en meta_proyecto.', faltantes;
    END IF;
END $$;

INSERT INTO propuesta_ciudadana
(codigo_propuesta, id_meta, nombre_propuesta, metodologia, tipo_acuerdo)
SELECT
    s.codigo_propuesta,
    m.id_meta,
    s.nombre_propuesta,
    s.metodologia,
    s.tipo_acuerdo
FROM stg_propuesta_ciudadana s
JOIN meta_proyecto m
  ON m.codigo_meta_extendida = s.codigo_meta_extendida
ON CONFLICT (codigo_propuesta)
DO UPDATE SET
    id_meta = EXCLUDED.id_meta,
    nombre_propuesta = EXCLUDED.nombre_propuesta,
    metodologia = EXCLUDED.metodologia,
    tipo_acuerdo = EXCLUDED.tipo_acuerdo;


