INSERT INTO seguimiento_propuesta
(id_propuesta, vigencia_ejecucion, fecha_corte, se_ejecuta_con_recursos,
 estado_propuesta, poblacion_beneficiada, clasificacion_poblacional,
 avance_gestion, dificultades)
SELECT
    p.id_propuesta,
    s.vigencia_ejecucion,
    s.fecha_corte,
    s.se_ejecuta_con_recursos,
    s.estado_propuesta,
    s.poblacion_beneficiada,
    s.clasificacion_poblacional,
    s.avance_gestion,
    s.dificultades
FROM stg_seguimiento_propuesta s
JOIN propuesta_ciudadana p
  ON p.codigo_propuesta = s.codigo_propuesta
ON CONFLICT (id_propuesta, fecha_corte)
DO UPDATE SET
    vigencia_ejecucion = EXCLUDED.vigencia_ejecucion,
    se_ejecuta_con_recursos = EXCLUDED.se_ejecuta_con_recursos,
    estado_propuesta = EXCLUDED.estado_propuesta,
    poblacion_beneficiada = EXCLUDED.poblacion_beneficiada,
    clasificacion_poblacional = EXCLUDED.clasificacion_poblacional,
    avance_gestion = EXCLUDED.avance_gestion,
    dificultades = EXCLUDED.dificultades;

COMMIT;
